<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch,nextTick} from 'vue'
import {IconPlus,IconLock,IconUsers,IconDots,IconChevronRight,IconChevronLeft,IconPencil,IconKeyboard,IconCheck,IconX,IconEraser,IconArrowBackUp,IconArrowForwardUp,IconDownload,IconTrash,IconCircleFilled} from '@tabler/icons-vue'
import type {components} from '../../shared/api'
import type {SessionClient} from '../auth/session'
import InkPage from './InkPage.vue'
import type {Ink,Stroke} from './ink'
type Entry=components['schemas']['JournalView']
const props=defineProps<{client:SessionClient;ru:boolean;active:boolean;me:components['schemas']['MemberView'];participants:components['schemas']['ParticipantView'][]}>()
const entries=ref<Entry[]>([]),busy=ref(false),error=ref(''),selected=ref<Entry|null>(null),editing=ref(false),expanded=ref(''),deleting=ref<Entry|null>(null),discarding=ref(false)
const title=ref(''),text=ref(''),ink=ref<Ink|null>(null),visibility=ref<Entry['visibility']>('private'),readers=ref<string[]>([]),published=ref(false),refreshAudience=ref(false)
const textInput=ref<HTMLTextAreaElement|null>(null)
const inkDialog=ref<HTMLDialogElement|null>(null),accessDialog=ref<HTMLDialogElement|null>(null),confirmDialog=ref<HTMLDialogElement|null>(null),inkPage=ref<InstanceType<typeof InkPage>|null>(null)
const tool=ref<'pen'|'eraser'>('pen'),penColor=ref<Stroke['color']>('ivory'),penWidth=ref(.003),finger=ref(false),canUndo=ref(false),canRedo=ref(false)
let dateTimer:ReturnType<typeof setInterval>|undefined
const now=ref(Date.now())
const t=(en:string,ru:string)=>props.ru?ru:en
const today=computed(()=>new Intl.DateTimeFormat('en-CA',{timeZone:props.me.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(now.value)))
const day=(date:string)=>new Intl.DateTimeFormat(props.ru?'ru':'en',{day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))
const dateLabel=(date:string)=>date===today.value?t('Today · ','Сегодня · ')+day(date):day(date)
const name=(id:string)=>props.participants.find(p=>p.id===id)?.display_name??'—'
const groups=computed(()=>{const sorted=[...entries.value].sort((a,b)=>b.date.localeCompare(a.date)||b.created_at.localeCompare(a.created_at));const days=[...new Set([today.value,...sorted.map(e=>e.date)])].sort().reverse();return days.map(date=>({date,entries:sorted.filter(e=>e.date===date)}))})
const readerOptions=computed(()=>[...props.participants,...readers.value.filter(id=>!props.participants.some(p=>p.id===id)).map(id=>({id,display_name:id}))].filter(p=>p.id!==props.me.id))
const hasContent=computed(()=>!!text.value.trim()||!!ink.value?.strokes?.length)
const initial=ref('')
const snapshot=()=>JSON.stringify({title:title.value,text:text.value,ink:ink.value,visibility:visibility.value,readers:readers.value,published:published.value,refresh:refreshAudience.value})
const dirty=computed(()=>editing.value&&snapshot()!==initial.value)
async function load(){entries.value=await props.client.get<Entry[]>('/journal');if(!expanded.value)expanded.value=entries.value.find(e=>e.date===today.value&&e.author_id===props.me.id)?.id??''}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'NETWORK_ERROR'}finally{busy.value=false}}
onMounted(()=>{dateTimer=setInterval(()=>{now.value=Date.now()},60000);void run(load);window.addEventListener('beforeunload',beforeUnload)});onUnmounted(()=>{clearInterval(dateTimer);window.removeEventListener('beforeunload',beforeUnload)})
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
watch(()=>props.active,active=>{if(active&&!editing.value)void run(load)})
watch(()=>props.me.paused,()=>{entries.value=entries.value.filter(e=>e.author_id===props.me.id);void run(load)})
function edit(e:Entry|null){selected.value=e;title.value=e?.title??'';text.value=e?.text??'';ink.value=e?.handwriting?JSON.parse(JSON.stringify(e.handwriting)):null;visibility.value=e?.visibility??'private';readers.value=[...(e?.reader_ids??[])];published.value=e?.published??false;refreshAudience.value=false;editing.value=true;expanded.value=e?.id??'';initial.value=snapshot()}
function closeEditor(){if(dirty.value){discarding.value=true;void nextTick(()=>confirmDialog.value?.showModal())}else editing.value=false}
function discard(){editing.value=false;discarding.value=false;confirmDialog.value?.close()}
async function handwriting(){if(!editing.value)edit(null);tool.value='pen';await nextTick();inkDialog.value?.showModal()}
async function openEntryInk(e:Entry){if(e.author_id===props.me.id){edit(e);await handwriting()}else readInk(e)}
function readInk(e:Entry){selected.value=e;title.value=e.title;text.value=e.text;visibility.value=e.visibility;ink.value=e.handwriting??null;void nextTick(()=>inkDialog.value?.showModal())}
function keyboard(){inkDialog.value?.close();textInput.value?.focus()}
async function access(){await nextTick();accessDialog.value?.showModal()}
async function save(){if(!hasContent.value)return;await run(async()=>{const e=selected.value;const body={date:e?.date??today.value,title:title.value.trim()||t('Entry · ','Запись · ')+day(e?.date??today.value),text:text.value,handwriting:ink.value,mood:e?.mood??null,tags:e?.tags??[],visibility:visibility.value,reader_ids:visibility.value==='private'?[]:readers.value,published:published.value};const saved=e?await props.client.patch<Entry>(`/journal/${e.id}`,{...body,expected_version:e.revision,refresh_audience:refreshAudience.value}):await props.client.post<Entry>('/journal',body);editing.value=false;selected.value=null;expanded.value=saved.id;inkDialog.value?.close();accessDialog.value?.close();await load()})}
async function requestDelete(e:Entry){deleting.value=e;await nextTick();confirmDialog.value?.showModal()}
async function remove(){const e=deleting.value;if(!e)return;await run(async()=>{await props.client.post(`/journal/${e.id}/delete`,{expected_version:e.revision});deleting.value=null;confirmDialog.value?.close();await load()})}
async function exportEntries(){await run(async()=>{const rows=await props.client.get<Entry[]>('/journal/export'),url=URL.createObjectURL(new Blob([JSON.stringify(rows,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='vowen-diary.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
</script>
<template>
<section id="journal" class="journal-timeline" :aria-label="t('Diary','Дневник')">
 <div class="journal-actions"><span class="journal-private"><IconLock :size="14" />{{t('Private by default','Только вам по умолчанию')}}</span><button class="journal-icon" :aria-label="t('New diary entry','Новая запись дневника')" :title="t('New diary entry','Новая запись дневника')" :disabled="busy||editing" @click="edit(null)"><IconPlus :size="19" /></button><details class="journal-overflow"><summary :aria-label="t('Diary actions','Действия дневника')"><IconDots :size="20" /></summary><button class="quiet-button" :disabled="busy" @click="exportEntries"><IconDownload :size="16" />{{t('Export','Экспорт')}}</button></details></div>
 <p v-if="error" role="alert">{{error}}</p>
 <div v-for="group in groups" :key="group.date" class="journal-day" :class="{'journal-today':group.date===today}">
  <h2>{{dateLabel(group.date)}}</h2>
  <div v-if="editing&&(selected?.date??today)===group.date" class="journal-writing">
   <header><input v-model="title" :aria-label="t('Entry title','Заголовок записи')" :placeholder="t('Entry title','Название записи')" maxlength="200"><button class="quiet-button journal-access" @click="access"><component :is="visibility==='private'?IconLock:IconUsers" :size="16" />{{visibility==='private'?t('Only me','Только мне'):t('Readers','Читатели')}}</button><button class="quiet-button journal-icon" :aria-label="t('Close editor','Закрыть редактор')" @click="closeEditor"><IconX :size="18" /></button></header>
   <textarea ref="textInput" v-model="text" class="journal-text-input" :aria-label="t('Entry text','Текст записи')" :placeholder="t('What would you like to remember?','Что хочется запомнить?')" maxlength="100000" rows="5" />
   <button v-if="ink?.strokes?.length" class="quiet-button journal-ink-preview" :aria-label="t('Open handwriting','Открыть рукопись')" @click="handwriting"><InkPage :model-value="ink" readonly :ru="ru" /></button>
   <div class="journal-writing-tools"><button class="quiet-button journal-icon" :aria-label="t('Write by hand','Писать от руки')" :title="t('Write by hand','Писать от руки')" @click="handwriting"><IconPencil :size="19" /></button><span>{{t('Text or handwriting','Текст или рукопись')}}</span><button class="journal-icon" :aria-label="t('Save diary entry','Сохранить запись дневника')" :title="t('Save diary entry','Сохранить запись дневника')" :disabled="busy||!hasContent" @click="save"><IconCheck :size="20" /></button></div>
  </div>
  <div v-if="!group.entries.length&&!(editing&&group.date===today)" class="journal-empty"><p>{{t('No entry for today yet.','Сегодня ещё нет записи.')}}</p><button class="quiet-button" :disabled="busy||editing" @click="edit(null)"><IconPlus :size="17" />{{t('Write something','Записать мысль')}}</button></div>
  <article v-for="e in group.entries.filter(e=>!editing||e.id!==selected?.id)" :key="e.id" class="journal-entry" :class="{'journal-entry-open':expanded===e.id}">
   <header><button class="quiet-button journal-entry-title" :aria-expanded="expanded===e.id" @click="expanded=expanded===e.id?'':e.id"><h3>{{e.title}}</h3><small v-if="e.author_id!==me.id">{{name(e.author_id)}}</small></button><span v-if="expanded===e.id" class="journal-entry-access"><component :is="e.visibility==='private'?IconLock:IconUsers" :size="14" />{{e.visibility==='private'?t('Only me','Только мне'):t('Shared','Открыт читателям')}}</span><details v-if="e.author_id===me.id" class="journal-overflow"><summary :aria-label="t('Entry actions: ','Действия записи: ')+e.title"><IconDots :size="20" /></summary><div><button class="quiet-button" :disabled="busy||editing" @click="edit(e)"><IconPencil :size="16" />{{t('Edit','Изменить')}}</button><button class="quiet-button" :disabled="busy" @click="requestDelete(e)"><IconTrash :size="16" />{{t('Delete','Удалить')}}</button></div></details><button v-else class="quiet-button journal-icon" :aria-label="t('Open entry','Открыть запись')" @click="expanded=e.id"><IconChevronRight :size="18" /></button></header>
   <template v-if="expanded===e.id"><p v-if="e.text" class="entry-text">{{e.text}}</p><button v-if="e.handwriting?.strokes?.length" class="quiet-button journal-ink-preview" :aria-label="t('Open handwriting','Открыть рукопись')" :disabled="busy||editing" @click="openEntryInk(e)"><InkPage :model-value="e.handwriting" readonly :ru="ru" /></button><button v-if="e.author_id===me.id" class="quiet-button journal-edit-link" :disabled="busy||editing" @click="edit(e)"><IconPencil :size="17" />{{t('Continue writing','Продолжить запись')}}</button><button v-else-if="e.handwriting?.strokes?.length" class="quiet-button" @click="readInk(e)">{{t('Open handwriting','Открыть рукопись')}}</button></template>
   <p v-else class="journal-entry-preview">{{e.text||t('Handwritten entry','Рукописная запись')}}</p>
  </article>
 </div>
 <dialog ref="inkDialog" class="journal-ink-dialog" :aria-label="t('Handwriting','Рукописный ввод')">
  <header><button class="quiet-button journal-ink-back" :aria-label="t('Back to diary','Назад в дневник')" @click="inkDialog?.close()"><IconChevronLeft :size="19" /><span>{{t('Diary','Дневник')}}</span></button><time>{{dateLabel(selected?.date??today)}}</time><IconLock v-if="visibility==='private'" :size="18" /><button v-if="editing" class="journal-icon" :disabled="busy||!hasContent" :aria-label="t('Save diary entry','Сохранить запись дневника')" @click="save"><IconCheck :size="22" /></button></header>
  <div class="journal-ink-heading"><h2>{{title||selected?.title||t('Today’s entry','Запись за сегодня')}}</h2><small><IconLock :size="13" />{{visibility==='private'?t('Only me','Только мне'):t('Shared','Открыт читателям')}}</small><p v-if="text">{{text}}</p></div>
  <div class="journal-ink-body"><div class="journal-paper-scroll"><InkPage ref="inkPage" v-model="ink" :readonly="!editing" :tool="tool" :color="penColor" :width="penWidth" :finger="finger" :ru="ru" @history="canUndo=$event.undo;canRedo=$event.redo" @limit="error=t('Page is full. Save this entry and start another.','Лист заполнен. Сохраните запись и начните новую.')" /></div>
   <aside v-if="editing" class="journal-pen-tools" :aria-label="t('Pen tools','Инструменты письма')"><button :aria-pressed="tool==='pen'" :aria-label="t('Pen','Перо')" @click="tool='pen'"><IconPencil :size="20" /></button><button :aria-pressed="tool==='eraser'" :aria-label="t('Eraser','Ластик')" @click="tool='eraser'"><IconEraser :size="20" /></button><button :disabled="!canUndo" :aria-label="t('Undo','Отменить штрих')" @click="inkPage?.undo()"><IconArrowBackUp :size="20" /></button><button :disabled="!canRedo" :aria-label="t('Redo','Вернуть штрих')" @click="inkPage?.redo()"><IconArrowForwardUp :size="20" /></button><button :aria-label="t('Keyboard','Клавиатура')" @click="keyboard"><IconKeyboard :size="20" /></button><button :aria-label="t('Pen width: ','Толщина пера: ')+(penWidth===.002?t('thin','тонко'):penWidth===.003?t('medium','средне'):t('thick','толсто'))" :title="t('Change pen width','Изменить толщину пера')" @click="penWidth=penWidth===.002?.003:penWidth===.003?.006:.002"><IconCircleFilled :size="penWidth===.002?5:penWidth===.003?8:12" /></button></aside>
  </div>
  <footer v-if="editing"><label><input v-model="finger" type="checkbox">{{t('Draw with finger','Писать пальцем')}}</label><span>{{t('Pen input works without enabling finger drawing.','Перо работает без включения письма пальцем.')}}</span></footer><p v-if="error" role="alert">{{error}}</p>
 </dialog>
 <dialog ref="accessDialog" class="journal-small-dialog" :aria-label="t('Entry access','Доступ к записи')"><header><h3>{{t('Entry access','Доступ к записи')}}</h3><button class="quiet-button journal-icon" :aria-label="t('Close','Закрыть')" @click="accessDialog?.close()"><IconX :size="18" /></button></header><label>{{t('Who can read','Кто может читать')}}<select v-model="visibility"><option value="private">{{t('Only me','Только мне')}}</option><option value="selected">{{t('Selected readers','Выбранные читатели')}}</option><option value="all_current_members">{{t('Current members','Текущие участники')}}</option></select></label><fieldset v-if="visibility==='selected'"><legend>{{t('Readers','Читатели')}}</legend><label v-for="p in readerOptions" :key="p.id"><input v-model="readers" type="checkbox" :value="p.id">{{p.display_name}}</label></fieldset><template v-if="visibility!=='private'"><label><input v-model="published" type="checkbox">{{t('Allow reading after saving','Разрешить чтение после сохранения')}}</label><p>{{t('Drafts stay visible only to you.','Черновик остаётся виден только вам.')}}</p><template v-if="visibility==='all_current_members'"><p>{{t('Future members are not added automatically.','Будущие участники не добавляются автоматически.')}}</p><label v-if="selected"><input v-model="refreshAudience" type="checkbox">{{t('Update member list explicitly','Обновить список участников')}}</label></template></template><button @click="accessDialog?.close()">{{t('Done','Готово')}}</button></dialog>
 <dialog ref="confirmDialog" class="journal-small-dialog" :aria-label="t('Confirm','Подтверждение')" @cancel="deleting=null;discarding=false"><h3>{{discarding?t('Discard changes?','Не сохранять изменения?'):t('Delete entry?','Удалить запись?')}}</h3><p>{{discarding?t('Your unsaved text and handwriting will be lost.','Несохранённые текст и рукопись будут потеряны.'):deleting?.title}}</p><button :disabled="busy" @click="discarding?discard():remove()">{{discarding?t('Discard','Не сохранять'):t('Delete','Удалить')}}</button><button class="quiet-button" @click="confirmDialog?.close();deleting=null;discarding=false">{{t('Cancel','Отмена')}}</button></dialog>
</section>
</template>
